#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase", tag = "type", content = "payload")]
pub(crate) enum SessionErrorEvent {
    HostKeyUnknown {
        session_id: String,
        host: String,
        port: u16,
        fingerprint: Option<String>,
    },
    HostKeyMismatch {
        session_id: String,
        host: String,
        port: u16,
        #[serde(skip_serializing_if = "Option::is_none")]
        fingerprint: Option<String>,
    },
}
